import csv
import re

# Load CSV people
people = []
with open('/app/dataset/people_accounts.csv') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        if row:
            people.append((row[0], row[1], int(row[2])))

# Load Tree
with open('/app/dataset/genealogy_trees.txt') as f:
    lines = [line.rstrip('\n') for line in f]

# Build index of name coordinates
person_coords = {}
person_by_coord = {}
for first, last, bal in people:
    pattern = re.compile(re.escape(first) + r'\s+' + re.escape(last))
    found = False
    for r, line in enumerate(lines):
        for m in pattern.finditer(line):
            coords = set((r, c) for c in range(m.start(), m.end()))
            person_coords[(first, last)] = coords
            for r_c, c_c in coords:
                person_by_coord[(r_c, c_c)] = (first, last)
            found = True
            break
        if found:
            break
    if not found:
        # Try split across lines
        for r in range(len(lines) - 1):
            if first in lines[r] and last in lines[r+1]:
                idx_f = lines[r].find(first)
                idx_l = lines[r+1].find(last)
                if abs(idx_f - idx_l) < 20:
                    coords = set()
                    for c in range(idx_f, idx_f + len(first)):
                        coords.add((r, c))
                    for c in range(idx_l, idx_l + len(last)):
                        coords.add((r + 1, c))
                    person_coords[(first, last)] = coords
                    for r_c, c_c in coords:
                        person_by_coord[(r_c, c_c)] = (first, last)
                    found = True
                    break
            elif last in lines[r] and first in lines[r+1]:
                idx_l = lines[r].find(last)
                idx_f = lines[r+1].find(first)
                if abs(idx_f - idx_l) < 20:
                    coords = set()
                    for c in range(idx_l, idx_l + len(last)):
                        coords.add((r, c))
                    for c in range(idx_f, idx_f + len(first)):
                        coords.add((r + 1, c))
                    person_coords[(first, last)] = coords
                    for r_c, c_c in coords:
                        person_by_coord[(r_c, c_c)] = (first, last)
                    found = True
                    break

print(f'Indexed {len(person_coords)} people.')

def get_char(r, c):
    if 0 <= r < len(lines) and 0 <= c < len(lines[r]):
        return lines[r][c]
    return ' '

# Trace children of Przemysław Kurczab
p_name = ('Przemysław', 'Kurczab')
p_cells = person_coords[p_name]
print('Przemysław Kurczab cells:', sorted(list(p_cells)))

# 1. Find bottom row of the box
r_name = min(r for r, c in p_cells)
bottom_row = -1
for r_test in range(r_name + 1, r_name + 5):
    span_chars = [get_char(r_test, col) for col in range(min(c for r, c in p_cells) - 5, max(c for r, c in p_cells) + 5)]
    if any(char in '+-~_│' for char in span_chars):
        bottom_row = r_test
        break
print('Bottom row of box:', bottom_row + 1)

# 2. Find vertical line going down
start_col = -1
for col_test in range(min(c for r, c in p_cells) - 5, max(c for r, c in p_cells) + 10):
    if get_char(bottom_row + 1, col_test) in '|│/\\':
        start_col = col_test
        break
print('Found vertical line start at:', bottom_row + 2, start_col)

# 3. Follow vertical line down
v_row = bottom_row + 1
v_col = start_col
v_path = [(v_row, v_col)]
h_row = -1
h_col_start = -1

while True:
    next_row = v_row + 1
    found_horiz = False
    # Check if we hit a horizontal-like character
    for dc in [-3, -2, -1, 0, 1, 2, 3]:
        ch1 = get_char(next_row, v_col + dc)
        ch2 = get_char(next_row, v_col + dc + (1 if dc>=0 else -1))
        if ch1 in '-~_+' and ch2 in '-~_+':
            found_horiz = True
            break
    if found_horiz:
        h_row = next_row
        h_col_start = v_col
        break

    # Otherwise, continue going down
    next_col = -1
    for dc in [0, -1, 1, -2, 2]:
        if get_char(next_row, v_col + dc) in '|│/\\':
            next_col = v_col + dc
            break
    if next_col == -1:
        for dc in [0, -1, 1, -2, 2]:
            ch = get_char(next_row, v_col + dc)
            if ch != ' ' and not ch.isalnum():
                next_col = v_col + dc
                break
    if next_col == -1:
        print('Vertical path ended prematurely.')
        break
    v_row = next_row
    v_col = next_col
    v_path.append((v_row, v_col))

print('Horizontal line row:', h_row + 1)

# 4. Trace the horizontal line on h_row
h_visited = set()
h_queue = [(h_row, h_col_start)]
h_cells = set()

while h_queue:
    curr_r, curr_c = h_queue.pop(0)
    if (curr_r, curr_c) in h_visited:
        continue
    h_visited.add((curr_r, curr_c))
    h_cells.add((curr_r, curr_c))

    # Explore neighbors horizontally
    for dr in [-1, 0, 1]:
        for dc in [-2, -1, 1, 2]: # allow jumping up to 1 space gap (step of 2)
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < len(lines) and 0 <= nc < len(lines[nr]):
                ch = lines[nr][nc]
                if ch in '-~_+=' or (ch != ' ' and not ch.isalnum()):
                    if (nr, nc) not in h_visited:
                        h_queue.append((nr, nc))

print('Total horizontal line cells:', len(h_cells))

# 5. From the horizontal line cells, find all vertical lines going down
down_starts = set()
for r, c in h_cells:
    # Check row r+1 or r+2
    for dr in [1, 2]:
        for dc in [-1, 0, 1]:
            nr, nc = r + dr, c + dc
            if get_char(nr, nc) in '|│/\\':
                # Group adjacent cols to avoid duplicate vertical lines
                # We can store (nr, nc)
                down_starts.add((nr, nc))

# Group down_starts that are very close (same row, cols within 5 of each other)
unique_down_starts = []
for nr, nc in sorted(list(down_starts)):
    # Check if we already have a starting point close to this
    is_new = True
    for u_r, u_c in unique_down_starts:
        if abs(u_r - nr) <= 1 and abs(u_c - nc) <= 5:
            is_new = False
            break
    if is_new:
        unique_down_starts.append((nr, nc))

print('Found unique downward line starts:', unique_down_starts)

# 6. For each start, trace downwards to find the child box
children_found = []
for start_r, start_c in unique_down_starts:
    curr_r, curr_c = start_r, start_c
    path = [(curr_r, curr_c)]
    found_child_name = None

    # Trace down up to 15 rows
    for step in range(15):
        # Check if we are near any person's name
        # A person is near if their name cells are within 3 rows below and 15 columns left/right
        candidate_people = []
        for (f, l), coords in person_coords.items():
            for name_r, name_c in coords:
                if 0 <= name_r - curr_r <= 4 and abs(name_c - curr_c) <= 12:
                    candidate_people.append((f, l))
                    break
        if candidate_people:
            # Found child!
            found_child_name = candidate_people[0] # take first matching
            break

        # Move down
        next_r = curr_r + 1
        next_c = -1
        # Try finding a vertical char
        for dc in [0, -1, 1, -2, 2]:
            if get_char(next_r, curr_c + dc) in '|│/\\':
                next_c = curr_c + dc
                break
        if next_c == -1:
            # Try any non-space
            for dc in [0, -1, 1, -2, 2]:
                ch = get_char(next_r, curr_c + dc)
                if ch != ' ':
                    next_c = curr_c + dc
                    break
        if next_c == -1:
            # If line ends, stop tracing this branch
            break
        curr_r = next_r
        curr_c = next_c
        path.append((curr_r, curr_c))

    if found_child_name:
        children_found.append((found_child_name, (start_r, start_c)))

print('Children of Przemysław Kurczab found:')
for child, pos in children_found:
    print(f'- {child[0]} {child[1]} starting from {pos}')

import csv
import re

# Load CSV people
people = []
with open('/app/dataset/people_accounts.csv') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        if row:
