                    found = True
                    break

print(f'Indexed {len(person_coords)} people.')

def get_char(r, c):
    if 0 <= r < len(lines) and 0 <= c < len(lines[r]):
        return lines[r][c]
    return ' '

def get_children(first, last):
    if (first, last) not in person_coords:
        return []
    p_cells = person_coords[(first, last)]
    r_name = min(r for r, c in p_cells)

    # 1. Find bottom row of the box
    bottom_row = -1
    for r_test in range(r_name + 1, r_name + 5):
        span_chars = [get_char(r_test, col) for col in range(min(c for r, c in p_cells) - 5, max(c for r, c in p_cells) + 5)]
        if any(char in '+-~_│=' for char in span_chars):
            bottom_row = r_test
            break
