    for col_test in range(min(c for r, c in p_cells) - 5, max(c for r, c in p_cells) + 10):
        if get_char(bottom_row + 1, col_test) in '|│/\\':
            start_col = col_test
            break
    if start_col == -1:
        # Try a bit wider
        for col_test in range(min(c for r, c in p_cells) - 15, max(c for r, c in p_cells) + 15):
            if get_char(bottom_row + 1, col_test) in '|│/\\':
                start_col = col_test
                break
    if start_col == -1:
        return []

    # 3. Follow vertical line down
    v_row = bottom_row + 1
    v_col = start_col
    h_row = -1
    h_col_start = -1

    # Trace down up to 30 rows
    for i in range(30):
