        return []

    # 4. Trace the horizontal line on h_row
    h_visited = set()
    h_queue = [(h_row, h_col_start)]
    h_cells = set()

    while h_queue:
        curr_r, curr_c = h_queue.pop(0)
        if (curr_r, curr_c) in h_visited:
            continue
        h_visited.add((curr_r, curr_c))
        h_cells.add((curr_r, curr_c))

        for dr in [-1, 0, 1]:
            for dc in [-2, -1, 1, 2]: # allow jumping up to 1 space gap
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < len(lines) and 0 <= nc < len(lines[nr]):
                    ch = lines[nr][nc]
                    if ch in '-~_+=' or (ch != ' ' and not ch.isalnum()):
