                            h_queue.append((nr, nc))

    # 5. Find downward line starts
    down_starts = set()
    for r, c in h_cells:
        for dr in [1, 2]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if get_char(nr, nc) in '|│/\\':
