    children_found = []
    for start_r, start_c in unique_down_starts:
        curr_r, curr_c = start_r, start_c
        found_child = None

        for step in range(15):
            candidate_people = []
            for (f, l), coords in person_coords.items():
                if (f, l) == (first, last):
                    continue
                for name_r, name_c in coords:
                    if 0 <= name_r - curr_r <= 4 and abs(name_c - curr_c) <= 12:
                        candidate_people.append((f, l))
                        break
