                    next_c = curr_c + dc
                    break
            if next_c == -1:
                for dc in [0, -1, 1, -2, 2]:
                    ch = get_char(next_r, curr_c + dc)
                    if ch != ' ':
                        next_c = curr_c + dc
                        break
            if next_c == -1:
                break
            curr_r = next_r
            curr_c = next_c

        if found_child and found_child not in children_found:
            children_found.append(found_child)

    return children_found

# Recursive print helper
def print_tree(first, last, depth=0):
    children = get_children(first, last)
    indent = '  ' * depth
    print(f'{indent}- {first} {last} (children: {len(children)})')
    for c_f, c_l in children:
        print_tree(c_f, c_l, depth + 1)

# Let's print the descendants of Przemysław Kurczab!
print_tree('Przemysław', 'Kurczab')

